// Проверка полноты данных за последние 10 месяцев
// ОПТИМИЗАЦИЯ: Разбиваем конкурентов на группы по 5 сайтов (ограничение SimilarWeb)
// v3: Проверяем ВСЕ записи в очереди (любой статус) для предотвращения дубликатов
const competitors = $('Читаем всех конкурентов').all();

// Читаем существующую очередь чтобы не дублировать задачи
let existingQueue = [];
try {
  existingQueue = $('Читаем очередь (проверка)').all();
} catch (e) {
  // Очередь может быть пустой
}

// Максимум сайтов в одном запросе SimilarWeb (клиент + 4 конкурента)
const MAX_SITES_PER_REQUEST = 5;

// Функция нормализации домена (убираем https://, www., trailing slash)
function normalizeDomain(url) {
  if (!url) return '';
  return url
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/+$/, '')
    .toLowerCase()
    .trim();
}

// Генерируем список последних 10 месяцев (с учётом задержки SimilarWeb в 2 месяца)
// SimilarWeb не показывает данные за последние 2 месяца
function getLast10Months() {
  const months = [];
  const now = new Date();

  // Начинаем с 3-го месяца назад (пропускаем текущий и предыдущий)
  for (let i = 3; i <= 12; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    months.push(`${year}.${month}`);
  }

  return months;
}

const last10Months = getLast10Months();

// Группируем конкурентов по клиентам (с нормализацией доменов)
const clientCompetitors = new Map();

competitors.forEach(row => {
  const client = normalizeDomain(row.json.client_site);
  const competitor = normalizeDomain(row.json.competitors_site);

  if (client && competitor) {
    if (!clientCompetitors.has(client)) {
      clientCompetitors.set(client, []);
    }
    if (!clientCompetitors.get(client).includes(competitor)) {
      clientCompetitors.get(client).push(competitor);
    }
  }
});

// v3: Собираем ВСЕ существующие задачи в очереди (любой статус)
// Это предотвращает создание дубликатов для уже выполненных задач
const existingQueueKeys = new Set();
existingQueue.forEach(row => {
  // Учитываем ВСЕ записи независимо от статуса
  const key = `${row.json.client_site}_${row.json.period}_${row.json.sites_list}`;
  existingQueueKeys.add(key);
});

// Функция для разбиения массива на чанки
function chunkArray(array, chunkSize) {
  const chunks = [];
  for (let i = 0; i < array.length; i += chunkSize) {
    chunks.push(array.slice(i, i + chunkSize));
  }
  return chunks;
}

// Создаём задачи с разбиением на группы
const queueTasks = [];

clientCompetitors.forEach((competitorsList, clientSite) => {
  const competitorChunks = chunkArray(competitorsList, MAX_SITES_PER_REQUEST - 1);

  competitorChunks.forEach((chunk, chunkIndex) => {
    last10Months.forEach((period, periodIndex) => {
      const sitesInRequest = [clientSite, ...chunk];
      const sitesList = sitesInRequest.join(',');

      // Проверяем, есть ли уже такая задача в очереди (любой статус)
      const queueKey = `${clientSite}_${period}_${sitesList}`;
      if (existingQueueKeys.has(queueKey)) {
        return; // Пропускаем - задача уже существует
      }

      // Создаём новую задачу
      const taskId = `${clientSite}_${period}_chunk${chunkIndex}_${Date.now()}`;

      queueTasks.push({
        queue_id: taskId,
        client_site: clientSite,
        sites_list: sitesList,
        chunk_index: chunkIndex,
        total_chunks: competitorChunks.length,
        period: period,
        status: 'pending',
        priority: periodIndex,
        created_at: new Date().toISOString().replace('T', ' ').substring(0, 19),
        task_id: '',
        error_message: ''
      });
    });
  });
});

queueTasks.sort((a, b) => b.priority - a.priority);

const summary = {
  totalClients: clientCompetitors.size,
  totalTasks: queueTasks.length,
  skippedExisting: existingQueueKeys.size,
  periods: last10Months,
  maxSitesPerRequest: MAX_SITES_PER_REQUEST
};

console.log('Queue tasks summary:', summary);

if (queueTasks.length === 0) {
  return [{ json: { noNewTasks: true, summary } }];
}

return queueTasks.map(task => ({ json: task }));

// Берём до 9 задач из очереди и добавляем рандомные задержки
const items = $input.all();

if (items.length === 0) {
  return [];
}

// Берём максимум 9 задач (лимит Browse AI в час)
const tasksToProcess = items.slice(0, 9);

// Генерируем псевдо-рандомные задержки (3-7 минут между задачами)
const tasks = tasksToProcess.map((item, index) => {
  // Базовая задержка 3-4 минуты + рандом 0-3 минуты
  const baseDelay = 180 + Math.floor(Math.random() * 60); // 180-240 сек
  const randomExtra = Math.floor(Math.random() * 180); // 0-180 сек
  const delaySeconds = baseDelay + randomExtra; // 180-420 сек (3-7 мин)

  // Накопительная задержка для каждой задачи
  const cumulativeDelay = index * delaySeconds;

  return {
    json: {
      ...item.json,
      taskIndex: index,
      delaySeconds: cumulativeDelay,
      delayMinutes: Math.round(cumulativeDelay / 60),
      scheduledAt: new Date(Date.now() + cumulativeDelay * 1000).toISOString()
    }
  };
});

console.log(`Processing ${tasks.length} tasks with random delays`);

return tasks;

// Формируем URL для запуска роботов v4
// v4: Добавлен Marketing Channels Robot
const input = $input.first().json;

const sites = input.sites_list.split(",");

if (sites.length > 5) {
  console.warn(`WARNING: Too many sites (${sites.length}), truncating to 5`);
  sites.length = 5;
}

const sitesParam = sites.map(s => s.trim()).join(",");
const queueId = input.queue_id;
// Нормализуем период: 2025.2 -> 2025.02 (Google Sheets может убрать ведущий ноль)
const rawPeriod = String(input.period);
const [year, month] = rawPeriod.split('.');
const period = `${year}.${month.padStart(2, '0')}`;

// URL для каждого робота
// Performance - страница website-performance
const performanceUrl = `https://pro.similarweb.com/#/digitalsuite/websiteanalysis/overview/website-performance/*/804/${period}-${period}?webSource=Total&key=${sitesParam}&qid=${queueId}`;
// Marketing Channels - страница traffic-overview (другой путь и формат URL!)
const marketingChannelsUrl = `https://pro.similarweb.com/?#/digitalsuite/websiteanalysis/traffic-overview/*/804/${period}-${period}/?webSource=Total&key=${sitesParam}`;
// AI Traffic - страница ai-traffic
const aiTrafficUrl = `https://pro.similarweb.com/#/digitalsuite/ai-traffic/overview/*/804/${period}-${period}?webSource=Total&key=${sitesParam}&qid=${queueId}`;

return [{
  json: {
    ...input,
    performanceUrl,
    marketingChannelsUrl,
    aiTrafficUrl,
    sites: sitesParam,
    sitesCount: sites.length,
    period,
    queueId
  }
}];

// Парсер Marketing Channels v1.0
// Извлекает данные каналов: Direct, Organic Search, Paid Search, Display Ads, Social, Email
const input = $input.first().json;

const body = input.body || input;
const taskStatus = body?.task?.status || input.taskStatus;

if (taskStatus !== 'successful' && taskStatus !== 'completed') {
  return [{ json: { error: 'Task not successful', taskStatus, sheetsRows: [] } }];
}

const rawData = body?.task?.capturedTexts || {};
const taskId = body?.task?.id || input.taskId || 'unknown';
const originUrl = body?.task?.inputParameters?.originUrl || input.originUrl || '';

const keyMatch = originUrl.match(/key=([^&]+)/);
let sitesFromUrl = [];
if (keyMatch) {
  sitesFromUrl = decodeURIComponent(keyMatch[1]).split(',');
}
const clientSite = sitesFromUrl[0] || '';

const qidMatch = originUrl.match(/qid=([^&]+)/);
const queueId = qidMatch ? qidMatch[1] : '';

let periodFormatted = '';
const periodUrlMatch = originUrl.match(/\/804\/(\d{4}\.\d{1,2})-\d{4}\.\d{1,2}/);
if (periodUrlMatch) {
  const [y, m] = periodUrlMatch[1].split('.');
  periodFormatted = y + '.' + m.padStart(2, '0');
}
if (!periodFormatted && queueId) {
  const queuePeriodMatch = queueId.match(/_(\d{4}\.\d{1,2})_/);
  if (queuePeriodMatch) {
    const [y, m] = queuePeriodMatch[1].split('.');
    periodFormatted = y + '.' + m.padStart(2, '0');
  }
}
if (!periodFormatted) {
  // Fallback: извлекаем из URL параметра key через sitesFromUrl
  const now = new Date();
  periodFormatted = `${now.getFullYear()}.${String(now.getMonth() + 1).padStart(2, '0')}`;
}

let data = {};
if (Array.isArray(rawData)) {
  rawData.forEach(item => {
    const key = item.name || item.key;
    const value = item.newText || item.text || item.value;
    if (key && value) data[key] = value;
  });
} else {
  data = rawData;
}

function extractLegendData(html) {
  if (!html) return {};
  const sites = {};
  const patterns = [
    /data-automation-title="true"[^>]*>([^<]+)<\/label>[\s\S]*?data-automation-value="true"[^>]*>([^<]+)<\/label>/g,
    /class="[^"]*iUaIjL[^"]*">([^<]+)<\/label>[\s\S]{0,300}?class="[^"]*gzsEum[^"]*">([^<]+)<\/label>/g
  ];
  patterns.forEach(pattern => {
    let match;
    while ((match = pattern.exec(html)) !== null) {
      const site = match[1].trim();
      const value = match[2].trim();
      if (site && value && site.includes('.') && /^[a-zA-Z0-9]/.test(site)) {
        if (!sites[site]) sites[site] = value;
      }
    }
  });
  return sites;
}

const direct = extractLegendData(data['Direct']);
const organicSearch = extractLegendData(data['Organic Search']);
const paidSearch = extractLegendData(data['Paid Search']);
const displayAds = extractLegendData(data['Display Ads'] || data['Display Search']);
const social = extractLegendData(data['Social'] || data['Sosial']);
const email = extractLegendData(data['Email']);

const today = new Date().toISOString().split('T')[0];

const allSites = new Set();
[direct, organicSearch, paidSearch, displayAds, social, email].forEach(channel => {
  Object.keys(channel).forEach(site => allSites.add(site));
});
if (allSites.size === 0 && sitesFromUrl.length > 0) {
  sitesFromUrl.forEach(site => allSites.add(site));
}

const sitesArray = Array.from(allSites);

const sheetsRows = sitesArray.map((site) => ({
  'date': today,
  'period': periodFormatted,
  'client_site': clientSite,
  'site': site,
  'type': site === clientSite ? 'client' : 'competitor',
  'Monthly Visits': '',
  'Unique Visitors': '',
  'Visit Duration': '',
  'Pages/Visit': '',
  'Bounce Rate': '',
  'Direct': direct[site] || '',
  'Organic Search': organicSearch[site] || '',
  'Paid Search': paidSearch[site] || '',
  'Display Ads': displayAds[site] || '',
  'Social': social[site] || '',
  'Email': email[site] || '',
  'AI Traffic': '',
  'Task ID': taskId,
  'Queue ID': queueId,
  'key': `${periodFormatted}_${site}`
}));

return [{
  json: {
    taskId,
    queueId,
    type: 'marketing_channels',
    periodFormatted,
    clientSite,
    channels: { direct, organicSearch, paidSearch, displayAds, social, email },
    sheetsRows,
    sitesCount: sitesArray.length,
    raw: data
  }
}];

// Маршрутизация Marketing Channels в таблицу клиента
const clients = $('Читаем Клиенты для MC').all();
const mcRows = $('Split Out: Marketing Channels').all();

const clientMap = new Map();
clients.forEach(c => {
  if (c.json.client_site && c.json.spreadsheet_id) {
    clientMap.set(c.json.client_site, c.json.spreadsheet_id);
  }
});

const output = [];
mcRows.forEach(row => {
  const clientSite = row.json.client_site;
  const spreadsheetId = clientMap.get(clientSite);
  if (spreadsheetId) {
    output.push({ json: { ...row.json, _spreadsheet_id: spreadsheetId } });
  }
});

return output.length > 0 ? output : [{ json: { noClientData: true } }];

// Upsert логика Marketing Channels
const inputData = $('Есть MC данные клиента?').all();
const sheetResponse = $input.first().json;
const sheetValues = sheetResponse.values || [];
const spreadsheetId = inputData[0]?.json._spreadsheet_id;

// Нормализация периода: 2025.2 -> 2025.02
function normPeriod(p) {
  const s = String(p || '');
  const parts = s.split('.');
  if (parts.length === 2) return parts[0] + '.' + parts[1].padStart(2, '0');
  return s;
}

const existingRows = new Map();
for (let i = 1; i < sheetValues.length; i++) {
  const row = sheetValues[i];
  const period = normPeriod(row[1]);
  const site = row[3] || '';
  const key = `${period}_${site}`;
  existingRows.set(key, { rowIndex: i + 1, rowData: row });
}

const results = [];
for (const item of inputData) {
  const row = item.json;
  const key = `${normPeriod(row.period)}_${row.site}`;
  const existing = existingRows.get(key);

  const newRowData = [
    row.date || '', row.period || '', row.client_site || '', row.site || '', row.type || '',
    row['Monthly Visits'] || '', row['Unique Visitors'] || '', row['Visit Duration'] || '',
    row['Pages/Visit'] || '', row['Bounce Rate'] || '', row.Direct || '',
    row['Organic Search'] || '', row['Paid Search'] || '', row['Display Ads'] || '',
    row.Social || '', row.Email || '', row['AI Traffic'] || '',
    row['Task ID'] || '', row['Queue ID'] || '', row.key || ''
  ];

  if (existing) {
    const mergedData = newRowData.map((newVal, idx) => {
      if (newVal === '' && existing.rowData[idx]) return existing.rowData[idx];
      return newVal;
    });
    results.push({ json: { action: 'update', spreadsheetId, rowIndex: existing.rowIndex, range: `Данные!A${existing.rowIndex}:T${existing.rowIndex}`, values: [mergedData] } });
  } else {
    results.push({ json: { action: 'append', spreadsheetId, values: [newRowData] } });
  }
}

return results;

// Формируем отчёт из Marketing Channels данных
const data = $('Parse Marketing Channels Data').first().json;

let report = '🚦 <b>Marketing Channels</b>\n';
report += `📅 ${data.periodFormatted}\n`;
report += `👤 Клиент: ${data.clientSite}\n\n`;

const channels = data.channels;
const channelConfig = [
  { key: 'direct', name: 'Direct', emoji: '🔗' },
  { key: 'organicSearch', name: 'Organic Search', emoji: '🔍' },
  { key: 'paidSearch', name: 'Paid Search', emoji: '💰' },
  { key: 'displayAds', name: 'Display Ads', emoji: '📺' },
  { key: 'social', name: 'Social', emoji: '📱' },
  { key: 'email', name: 'Email', emoji: '📧' }
];

channelConfig.forEach(({ key, name, emoji }) => {
  const channelData = channels[key];
  if (channelData && Object.keys(channelData).length > 0) {
    report += `${emoji} <b>${name}</b>\n`;
    Object.entries(channelData).forEach(([site, value]) => {
      const siteEmoji = site === data.clientSite ? '🔵' : '🟠';
      report += `   ${siteEmoji} ${site}: ${value}\n`;
    });
    report += '\n';
  }
});

report += '━━━━━━━━━━━━━━━━━━━━━\n';
report += '✅ Каналы сохранены';

return [{ json: { report, ...data } }];

// Проверяем статус задачи и направляем на обработку или логирование ошибки
const input = $input.first().json;

const taskStatus = input.body?.task?.status || input.status;
const taskId = input.body?.task?.id || 'unknown';
const finishedAt = input.body?.task?.finishedAt;
const robotId = input.body?.robot?.id || 'unknown';
const originUrl = input.body?.task?.inputParameters?.originUrl || '';

// Определяем тип робота
const isPerformance = originUrl.includes('website-performance');
const robotType = isPerformance ? 'Performance' : 'AI Traffic';

// Извлекаем информацию из URL
const keyMatch = originUrl.match(/key=([^&]+)/);
let sites = [];
if (keyMatch) {
  sites = decodeURIComponent(keyMatch[1]).split(',');
}

const periodMatch = originUrl.match(/\/804\/(\d{4}\.\d{2})-/);
const period = periodMatch ? periodMatch[1] : 'unknown';

// Проверяем успешность
const isSuccess = (taskStatus === 'successful' || taskStatus === 'completed') && finishedAt;

if (!isSuccess) {
  // Задача провалилась - логируем ошибку
  // Поля соответствуют колонкам в таблице "Логи ошибок"
  return [{
    json: {
      isError: true,
      timestamp: new Date().toISOString().replace('T', ' ').substring(0, 19),
      task_id: taskId,
      robot_type: robotType,
      period: period,
      sites: sites.join(','),
      status: taskStatus || 'failed',
      error_message: input.body?.task?.failedReason || 'Unknown error',
      url: originUrl,
      // Дополнительные поля для обработки
      taskId,
      taskStatus,
      robotType,
      originUrl
    }
  }];
}

// Задача успешна - передаём на обработку
return [{
  json: {
    isError: false,
    taskId,
    taskStatus,
    robotType,
    period,
    sites,
    originUrl,
    body: input.body
  }
}];

