// Upsert логика: найти строку по period+site и обновить, или добавить новую
const inputData = $('Есть данные клиента?').all();
const sheetResponse = $input.first().json;
const sheetValues = sheetResponse.values || [];

// Получаем spreadsheet_id из первого item
const spreadsheetId = inputData[0]?.json._spreadsheet_id;

// Нормализация периода: 2025.2 -> 2025.02
function normPeriod(p) {
  const s = String(p || '');
  const parts = s.split('.');
  if (parts.length === 2) return parts[0] + '.' + parts[1].padStart(2, '0');
  return s;
}

// Создаём индекс существующих строк: "period_site" -> rowIndex
const existingRows = new Map();
for (let i = 1; i < sheetValues.length; i++) { // Skip header row
  const row = sheetValues[i];
  const period = normPeriod(row[1]); // Column B = period
  const site = row[3] || '';   // Column D = site
  const key = `${period}_${site}`;
  existingRows.set(key, {
    rowIndex: i + 1, // 1-based for Sheets API
    rowData: row
  });
}

const results = [];

for (const item of inputData) {
  const row = item.json;
  const key = `${normPeriod(row.period)}_${row.site}`;
  const existing = existingRows.get(key);

  // Подготавливаем данные строки
  const newRowData = [
    row.date || '',
    row.period || '',
    row.client_site || '',
    row.site || '',
    row.type || '',
    row['Monthly Visits'] || '',
    row['Unique Visitors'] || '',
    row['Visit Duration'] || '',
    row['Pages/Visit'] || '',
    row['Bounce Rate'] || '',
    row.Direct || '',
    row['Organic Search'] || '',
    row['Paid Search'] || '',
    row['Display Ads'] || '',
    row.Social || '',
    row.Email || '',
    row['AI Traffic'] || '',
    row['Task ID'] || '',
    row['Queue ID'] || '',
    row.key || ''
  ];

  if (existing) {
    // Merge: сохраняем существующие данные где новые пустые
    const mergedData = newRowData.map((newVal, idx) => {
      if (newVal === '' && existing.rowData[idx]) {
        return existing.rowData[idx];
      }
      return newVal;
    });

    results.push({
      json: {
        action: 'update',
        spreadsheetId,
        rowIndex: existing.rowIndex,
        range: `Данные!A${existing.rowIndex}:T${existing.rowIndex}`,
        values: [mergedData]
      }
    });
  } else {
    results.push({
      json: {
        action: 'append',
        spreadsheetId,
        values: [newRowData]
      }
    });
  }
}

return results;

